1	/**
2	 * Scoped per .claude/rules/testing.md: this component's OWN contract only — cap enforcement,
3	 * order preservation, empty-input renders null, and the See-Full-History link's presence gated
4	 * on `seeAllHref`. `ZimmProductCard`'s own internals (badge rendering, hover-swap, accessible-name
5	 * concatenation, etc.) are already covered by zimmProductCard/index.test.tsx and are deliberately
6	 * NOT re-tested here — testing.md's "no duplicate coverage across layers".
7	 *
8	 * `ZimmProductCard` is composed for real here (not mocked out) — same "costs nothing, gives real
9	 * integration confidence" precedent zimmProductCard/index.test.tsx and
10	 * zimmProductCardContent/index.test.tsx already document for their own composed children. Its own
11	 * `data-testid="product-card"` / `data-product-id` DOM hooks (zimmProductCard/index.tsx's own
12	 * docblock: "a DOM hook for QA automation/analytics") are what this file's cap/order assertions
13	 * read — a stable, intentional surface, not an internal implementation detail being reached into.
14	 *
15	 * `useMultiStyleConfig` is mocked with one flat object covering every part every composed
16	 * descendant reads (this component's own 5 parts, plus ZimmProductCard's `root` and
17	 * ZimmProductCardMedia's 12 parts) — same "neither test setup nor Chakra cares which recipe name
18	 * asked for it" precedent zimmProductCard/index.test.tsx and zimmProductCardMedia/index.test.tsx
19	 * document. `ZimmProductCardContent` never mounts for the `recentlyViewed` variation
20	 * (`VARIATION_CONFIG.showContent` is false there), so its own parts are not needed here.
21	 *
22	 * The icon-module mocks below are the same known Vitest SVG-import issue documented in
23	 * .claude/rules/testing.md ("Known gap: ZimmIcon throws under Vitest") and already mocked in
24	 * zimmProductCard/index.test.tsx — copied verbatim since this file sits at the identical
25	 * ui-kits/organisms/<name>/ depth, so the same relative specifiers resolve to the same modules.
26	 *
27	 * No `react-router-dom` mock (unlike zimmProductCard/index.test.tsx's own `useHistory` spy) —
28	 * this component never calls `useHistory` itself, and `ZimmProductCard`'s own click-passthrough
29	 * mechanism is already covered by that file's own tests, not re-proven here.
30	 */
31	import React from 'react';
32	import { describe, test, expect, vi } from 'vitest';
33	import { render, screen } from '@testing-library/react';
34	import { IntlProvider } from 'react-intl';
35	import { MemoryRouter } from 'react-router-dom';
36	import { RECENTLY_VIEWED_RAIL_MAX_ITEMS } from 'app/constants';
37	import { ZimmRecentlyViewedRail } from './index';
38	import type { ZimmProductCardProps } from '../zimmProductCard';
39	
40	vi.mock('@chakra-ui/react', async (importOriginal) => {
41	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
42	  return {
43	    ...actual,
44	    useMultiStyleConfig: () => ({
45	      // ZimmRecentlyViewedRail (this component's own recipe).
46	      container: {},
47	      header: {},
48	      seeAllLink: {},
49	      group: {},
50	      card: {},
51	      // ZimmProductCard.
52	      root: {},
53	      // ZimmProductCardMedia.
54	      scrollContainer: {},
55	      slide: {},
56	      image: {},
57	      hoverSwapBase: {},
58	      hoverSwapOverlay: {},
59	      badge: {},
60	      badgeLabel: {},
61	      close: {},
62	      carousel: {},
63	      arrowButton: {},
64	      indicatorWrapper: {},
65	    }),
66	  };
67	});
68	
69	// ZimmIcon (used by ZimmProductCardContent's bag button, never mounted here but still statically
70	// imported by index.tsx's own import of ZimmProductCard) and the icons barrel (used by
71	// ZimmProductCardMedia's close/arrow buttons): known Vitest SVG side-effect issue documented in
72	// .claude/rules/testing.md's "Known gap: ZimmIcon throws under Vitest".
73	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
74	vi.mock('../../../icons', () => ({
75	  ChevronLeftIcon: () => null,
76	  ChevronRightIcon: () => null,
77	  CloseIcon: () => null,
78	}));
79	
80	const wrap = (ui: React.ReactElement) =>
81	  render(
82	    <MemoryRouter>
83	      <IntlProvider locale="en" defaultLocale="en">
84	        {ui}
85	      </IntlProvider>
86	    </MemoryRouter>,
87	  );
88	
89	const buildCard = (id: string): ZimmProductCardProps => ({
90	  id,
91	  variation: 'recentlyViewed',
92	  name: `Product ${id}`,
93	  headingLevel: 'h3',
94	  href: `/product/${id}`,
95	  primaryImage: { src: `${id}.jpg`, alt: '' },
96	});
97	
98	describe('ZimmRecentlyViewedRail — cap (RECENTLY_VIEWED_RAIL_MAX_ITEMS)', () => {
99	  test('renders at most RECENTLY_VIEWED_RAIL_MAX_ITEMS cards when more are supplied', () => {
100	    const cards = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'].map(buildCard);
101	    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
102	    expect(screen.getAllByTestId('product-card')).toHaveLength(RECENTLY_VIEWED_RAIL_MAX_ITEMS);
103	  });
104	
105	  test('renders exactly the number of cards supplied when under the cap', () => {
106	    const cards = ['a', 'b', 'c'].map(buildCard);
107	    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
108	    expect(screen.getAllByTestId('product-card')).toHaveLength(3);
109	  });
110	});
111	
112	describe('ZimmRecentlyViewedRail — order preservation (AC 2: most-recent-first, left to right)', () => {
113	  /**
114	   * Fail-first requirement: this fixture's correct and reversed renderings are visibly different
115	   * — a test asserting only "all 5 ids are present" would pass under either a correct or a
116	   * reversed implementation and is exactly the encoded-bug trap this fixture avoids. Proven by
117	   * temporarily adding `.reverse()` to this component's own `visibleCards` slice, confirming this
118	   * exact assertion failed (`Expected: ["a","b","c","d","e"], Received: ["e","d","c","b","a"]`),
119	   * then removing it and confirming this assertion passes again — see this step's own report for
120	   * the record of that run; no trace of the temporary change remains in index.tsx.
121	   */
122	  test('renders cards in the exact order received, not sorted or reversed', () => {
123	    const cards = ['a', 'b', 'c', 'd', 'e'].map(buildCard);
124	    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
125	    const renderedIds = screen.getAllByTestId('product-card').map((el) => el.getAttribute('data-product-id'));
126	    expect(renderedIds).toEqual(['a', 'b', 'c', 'd', 'e']);
127	  });
128	});
129	
130	describe('ZimmRecentlyViewedRail — empty state', () => {
131	  test('renders null when cards is empty', () => {
132	    const { container } = wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={[]} />);
133	    expect(container).toBeEmptyDOMElement();
134	  });
135	});
136	
137	describe('ZimmRecentlyViewedRail — See-Full-History link', () => {
138	  test('renders the link, pointed at seeAllHref, when seeAllHref is provided', () => {
139	    const cards = [buildCard('a')];
140	    wrap(
141	      <ZimmRecentlyViewedRail
142	        title="Recently Viewed"
143	        cards={cards}
144	        seeAllHref="/recently-viewed"
145	        seeAllLabel="See Full History"
146	      />,
147	    );
148	    expect(screen.getByRole('link', { name: 'See Full History' })).toHaveAttribute('href', '/recently-viewed');
149	  });
150	
151	  test('does not render the link when seeAllHref is absent', () => {
152	    const cards = [buildCard('a')];
153	    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
154	    expect(screen.queryByRole('link', { name: 'See Full History' })).not.toBeInTheDocument();
155	    // Only the one card's own link should be present — proves the query above isn't a false
156	    // negative from a broken selector (e.g. matching the wrong accessible name entirely).
157	    expect(screen.getAllByRole('link')).toHaveLength(1);
158	  });
159	});
160

