/**
 * Scoped per .claude/rules/testing.md: this component's OWN contract only — cap enforcement,
 * order preservation, empty-input renders null, and the See-Full-History link's presence gated
 * on `seeAllHref`. `ZimmProductCard`'s own internals (badge rendering, hover-swap, accessible-name
 * concatenation, etc.) are already covered by zimmProductCard/index.test.tsx and are deliberately
 * NOT re-tested here — testing.md's "no duplicate coverage across layers".
 *
 * `ZimmProductCard` is composed for real here (not mocked out) — same "costs nothing, gives real
 * integration confidence" precedent zimmProductCard/index.test.tsx and
 * zimmProductCardContent/index.test.tsx already document for their own composed children. Its own
 * `data-testid="product-card"` / `data-product-id` DOM hooks (zimmProductCard/index.tsx's own
 * docblock: "a DOM hook for QA automation/analytics") are what this file's cap/order assertions
 * read — a stable, intentional surface, not an internal implementation detail being reached into.
 *
 * `useMultiStyleConfig` is mocked with one flat object covering every part every composed
 * descendant reads (this component's own 5 parts, plus ZimmProductCard's `root` and
 * ZimmProductCardMedia's 12 parts) — same "neither test setup nor Chakra cares which recipe name
 * asked for it" precedent zimmProductCard/index.test.tsx and zimmProductCardMedia/index.test.tsx
 * document. `ZimmProductCardContent` never mounts for the `recentlyViewed` variation
 * (`VARIATION_CONFIG.showContent` is false there), so its own parts are not needed here.
 *
 * The icon-module mocks below are the same known Vitest SVG-import issue documented in
 * .claude/rules/testing.md ("Known gap: ZimmIcon throws under Vitest") and already mocked in
 * zimmProductCard/index.test.tsx — copied verbatim since this file sits at the identical
 * ui-kits/organisms/<name>/ depth, so the same relative specifiers resolve to the same modules.
 *
 * No `react-router-dom` mock (unlike zimmProductCard/index.test.tsx's own `useHistory` spy) —
 * this component never calls `useHistory` itself, and `ZimmProductCard`'s own click-passthrough
 * mechanism is already covered by that file's own tests, not re-proven here.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { RECENTLY_VIEWED_RAIL_MAX_ITEMS } from 'app/constants';
import { ZimmRecentlyViewedRail } from './index';
import type { ZimmProductCardProps } from '../zimmProductCard';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      // ZimmRecentlyViewedRail (this component's own recipe).
      container: {},
      header: {},
      seeAllLink: {},
      group: {},
      card: {},
      // ZimmProductCard.
      root: {},
      // ZimmProductCardMedia.
      scrollContainer: {},
      slide: {},
      image: {},
      hoverSwapBase: {},
      hoverSwapOverlay: {},
      badge: {},
      badgeLabel: {},
      close: {},
      carousel: {},
      arrowButton: {},
      indicatorWrapper: {},
    }),
  };
});

// ZimmIcon (used by ZimmProductCardContent's bag button, never mounted here but still statically
// imported by index.tsx's own import of ZimmProductCard) and the icons barrel (used by
// ZimmProductCardMedia's close/arrow buttons): known Vitest SVG side-effect issue documented in
// .claude/rules/testing.md's "Known gap: ZimmIcon throws under Vitest".
vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
vi.mock('../../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
  CloseIcon: () => null,
}));

const wrap = (ui: React.ReactElement) =>
  render(
    <MemoryRouter>
      <IntlProvider locale="en" defaultLocale="en">
        {ui}
      </IntlProvider>
    </MemoryRouter>,
  );

const buildCard = (id: string): ZimmProductCardProps => ({
  id,
  variation: 'recentlyViewed',
  name: `Product ${id}`,
  headingLevel: 'h3',
  href: `/product/${id}`,
  primaryImage: { src: `${id}.jpg`, alt: '' },
});

describe('ZimmRecentlyViewedRail — cap (RECENTLY_VIEWED_RAIL_MAX_ITEMS)', () => {
  test('renders at most RECENTLY_VIEWED_RAIL_MAX_ITEMS cards when more are supplied', () => {
    const cards = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'].map(buildCard);
    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
    expect(screen.getAllByTestId('product-card')).toHaveLength(RECENTLY_VIEWED_RAIL_MAX_ITEMS);
  });

  test('renders exactly the number of cards supplied when under the cap', () => {
    const cards = ['a', 'b', 'c'].map(buildCard);
    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
    expect(screen.getAllByTestId('product-card')).toHaveLength(3);
  });
});

describe('ZimmRecentlyViewedRail — order preservation (AC 2: most-recent-first, left to right)', () => {
  /**
   * Fail-first requirement: this fixture's correct and reversed renderings are visibly different
   * — a test asserting only "all 5 ids are present" would pass under either a correct or a
   * reversed implementation and is exactly the encoded-bug trap this fixture avoids. Proven by
   * temporarily adding `.reverse()` to this component's own `visibleCards` slice, confirming this
   * exact assertion failed (`Expected: ["a","b","c","d","e"], Received: ["e","d","c","b","a"]`),
   * then removing it and confirming this assertion passes again — see this step's own report for
   * the record of that run; no trace of the temporary change remains in index.tsx.
   */
  test('renders cards in the exact order received, not sorted or reversed', () => {
    const cards = ['a', 'b', 'c', 'd', 'e'].map(buildCard);
    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
    const renderedIds = screen.getAllByTestId('product-card').map((el) => el.getAttribute('data-product-id'));
    expect(renderedIds).toEqual(['a', 'b', 'c', 'd', 'e']);
  });
});

describe('ZimmRecentlyViewedRail — empty state', () => {
  test('renders null when cards is empty', () => {
    const { container } = wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={[]} />);
    expect(container).toBeEmptyDOMElement();
  });
});

describe('ZimmRecentlyViewedRail — See-Full-History link', () => {
  test('renders the link, pointed at seeAllHref, when seeAllHref is provided', () => {
    const cards = [buildCard('a')];
    wrap(
      <ZimmRecentlyViewedRail
        title="Recently Viewed"
        cards={cards}
        seeAllHref="/recently-viewed"
        seeAllLabel="See Full History"
      />,
    );
    expect(screen.getByRole('link', { name: 'See Full History' })).toHaveAttribute('href', '/recently-viewed');
  });

  test('does not render the link when seeAllHref is absent', () => {
    const cards = [buildCard('a')];
    wrap(<ZimmRecentlyViewedRail title="Recently Viewed" cards={cards} />);
    expect(screen.queryByRole('link', { name: 'See Full History' })).not.toBeInTheDocument();
    // Only the one card's own link should be present — proves the query above isn't a false
    // negative from a broken selector (e.g. matching the wrong accessible name entirely).
    expect(screen.getAllByRole('link')).toHaveLength(1);
  });
});

