 * `.claude/rules/testing.md`'s "no duplicate coverage across layers"), so there is nothing this
 * story needs live selection state for, unlike `zimmProductCard/index.stories.tsx`'s own
 * `LiveSizeSelectionCard` wrapper.
 */
const buildCards = (count: number): ZimmProductCardProps[] =>
  Array.from({ length: count }, (_, index) => {
    const id = `prod-${index + 1}`;
    return {
      id,
      variation: 'plp',
      name: `Natura Dress ${index + 1}`,
      headingLevel: 'h3',
      href: `/product/${id}`,
      primaryImage: CARD_IMAGE,
      currentPrice: '$595.00',
      badge: index % 3 === 0 ? 'Runway' : undefined,
    };
  });

/**
 * Simplified proxy for the real ICU-plural caller logic SFCC-84's Full History page container
 * (build plan §B2, not built by this step) will implement via `intl.formatMessage` — this
 * component owns no copy/intl of its own (index.tsx's own `itemCountLabel` JSDoc), so this story
 * file has no `react-intl` dependency either, matching `zimmRecentlyViewedRail/index.stories.tsx`.
 * Used consistently against each story's own `buildCards(N)` call below so `itemCountLabel` and
 * the actual rendered card count can never accidentally drift apart within this file — the "stays
 * in sync when a real caller wires them together correctly" proof this step's brief asked for.
 */
const buildItemCountLabel = (count: number): string => (count === 1 ? '1 Item' : `${count} Items`);

/**
 * SFCC-84 — build plan section B1. See index.tsx's own module docblock for the full component
 * contract (purely presentational, no cap/sort, empty-input renders null) and
 * zimmRecentlyViewedGrid.css.ts's own docblock for the confirmed/placeholder geometry these
 * stories render at whatever the current viewport happens to be — resize the preview (or use the
 * viewport addon) to see the 2-up (below `breakpoints.xl`) vs 4-up (`breakpoints.xl` and up) step.
 *
 * **Design source is provisional, independently-confirmed values are not** — see index.tsx's own
 * module docblock for why both are true; restated here rather than re-derived so a reviewer
 * opening only this file still gets the caveat.
 *
 * No fixed-width decorator `Box` here, matching `zimmRecentlyViewedRail/index.stories.tsx`'s own
 * reasoning: this is a full-bleed grid section, not a single card, so constraining it to a narrow
 * width would misrepresent it.
 */
const meta: Meta<typeof ZimmRecentlyViewedGrid> = {
  title: 'Commerce/ZimmRecentlyViewedGrid',
  component: ZimmRecentlyViewedGrid,
  parameters: { layout: 'padded' },
  decorators: [
    // Every card is a real ZimmProductCard, which renders a real react-router-dom Link — same
    // Router-context requirement zimmProductCard/index.stories.tsx and
    // zimmRecentlyViewedRail/index.stories.tsx document for themselves.
    (Story) => (
      <MemoryRouter>
        <Story />
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmRecentlyViewedGrid>;

/**
 * Baseline: 8 cards (two full 4-up desktop rows), demonstrating both the horizontal card gap and
 * the vertical row-to-row gap at once. `play` proves `itemCountLabel` and the actual rendered
 * card count agree — the "stays in sync when wired correctly" check this step's brief asked for,
 * since this component itself only trusts the prop (index.tsx's own `itemCountLabel` JSDoc).
 */
export const Default: Story = {
  args: {
    title: 'Recently Viewed',
    itemCountLabel: buildItemCountLabel(8),
    cards: buildCards(8),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const cards = await canvas.findAllByTestId('product-card');
    await expect(cards).toHaveLength(8);
    await expect(canvas.getByTestId('recently-viewed-grid-count')).toHaveTextContent(
      buildItemCountLabel(cards.length),
    );
    await expect(args.cards).toHaveLength(cards.length);
  },
};

/** A single card — proves the grid doesn't assume a minimum count, and that a lone item simply
 *  occupies the first cell rather than breaking the layout. Singular item-count copy
 *  ("1 Item", not "1 Items") is the caller's own responsibility (index.tsx's own `itemCountLabel`
 *  JSDoc) — demonstrated correctly wired here via the same `buildItemCountLabel` helper every
 *  other story in this file uses. */
export const SingleItem: Story = {
  args: {
    title: 'Recently Viewed',
    itemCountLabel: buildItemCountLabel(1),
    cards: buildCards(1),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const cards = await canvas.findAllByTestId('product-card');
    await expect(cards).toHaveLength(1);
    await expect(canvas.getByTestId('recently-viewed-grid-count')).toHaveTextContent('1 Item');
  },
};

/**
 * 24 cards — the real, designed ceiling for this surface: the Full History page container (build
 * plan §B2) caps its own fetch/display at `RECENTLY_VIEWED_HISTORY_MAX_STORED`
 * (`app/constants/index.ts`), which is itself set to match the Shopper Products `getProducts`
 * endpoint's own hard per-request ID limit — not an arbitrary "a lot of items" choice. This
 * organism enforces no cap of its own (contrast `ZimmRecentlyViewedRail`'s
 * `RECENTLY_VIEWED_RAIL_MAX_ITEMS` slice) — capping is the caller's job, per index.tsx's own
 * `cards` JSDoc — so this story renders all 24 to demonstrate six full desktop rows of vertical
 * gap in sequence.
 */
export const ManyItems: Story = {
  args: {
    title: 'Recently Viewed',
    itemCountLabel: buildItemCountLabel(24),
    cards: buildCards(24),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const cards = await canvas.findAllByTestId('product-card');
    await expect(cards).toHaveLength(24);
    await expect(canvas.getByTestId('recently-viewed-grid-count')).toHaveTextContent('24 Items');
  },
};

